```java
private List<ValidatedTransition> validateTransitions(List<TransitionInput> inputs,
                                                      List<ValidatedSegment> segments) {
    List<TransitionInput> safeInputs = inputs == null ? List.of() : inputs;
    Map<String, ValidatedSegment> byId = new HashMap<>();
    for (ValidatedSegment s : segments) byId.put(s.id(), s);

    // 解析淡化声明
    Map<String, ValidatedTransition> byNextId = new HashMap<>(); // key: toSegmentId
    List<ValidatedTransition> transitions = new ArrayList<>();
    for (TransitionInput input : safeInputs) {
        if (input.fromSegmentId() == null || input.toSegmentId() == null
                || input.durationMs() == null) throw badRequest("淡化的前后片段与时长不能为空");
        ValidatedSegment prev = byId.get(input.fromSegmentId());
        ValidatedSegment next = byId.get(input.toSegmentId());
        if (prev == null || next == null) throw badRequest("淡化引用的片段不存在于本草稿");
        if (prev.id().equals(next.id())) throw badRequest("淡化前后片段不能相同");
        long fadeMs = input.durationMs();
        if (fadeMs < 0 || fadeMs > CROSSFADE_MAX_FADE_MS)
            throw unprocessable("CROSSFADE_TOO_LONG", "淡化时长须在 0~10 秒: " + ...);
        if (byNextId.containsKey(next.id())) throw badRequest("同一片段重复声明淡化");
        String id = input.id() == null || input.id().isBlank() ? UUID.randomUUID().toString() : input.id();
        transitions.add(new ValidatedTransition(id, prev.id(), next.id(), fadeMs));
        byNextId.put(next.id(), ...);
    }

    // 时序与重叠规则
    List<ValidatedSegment> sorted = segments.stream().sorted(comparing startMs then id).toList();
    long maxEndBefore = Long.MIN_VALUE; // max end of segments before i-1
    for (int i = 0; i < sorted.size(); i++) {
        ValidatedSegment cur = sorted.get(i);
        if (i >= 2 && cur.startMs() < maxEndBefore) {
            throw unprocessable("CROSSFADE_TRIPLE_OVERLAP", ...);
        }
        if (i >= 1) {
            ValidatedSegment prevSeg = sorted.get(i - 1);
            ValidatedTransition t = byNextId.get(cur.id());
            boolean declared = t != null && t.fromSegmentId().equals(prevSeg.id());
            if (t != null && !declared) {
                throw unprocessable("TRANSITION_NOT_ADJACENT", "淡化前后片段在时间上不相邻: " + t.fromSegmentId() + " -> " + t.toSegmentId());
            }
            long overlapMs = prevSeg.endMs() - cur.startMs();
            if (declared) {
                if (cur.startMs() != prevSeg.endMs() - t.fadeMs()) {
                    throw unprocessable("CROSSFADE_TIMING_MISMATCH", "后一片段开始须等于前一片段结束减淡化时长");
                }
                // fade <= 两素材任一时长
                if (t.fadeMs() > prevSeg.durationMs() || t.fadeMs() > cur.durationMs()) {
                    throw unprocessable("CROSSFADE_TOO_LONG", "淡化时长不得超过两素材任一时长");
                }
            } else if (overlapMs > 0) {
                throw unprocessable("SEGMENT_OVERLAP", "片段时间重叠且未声明交叉淡化: ...");
            }
        }
        if (i >= 1) maxEndBefore = Math.max(maxEndBefore, sorted.get(i - 1).endMs());
    }
```

